        std::cout<<"],\"loads\":[";for(size_t i=0;i<loads.size();++i){if(i)std::cout<<',';std::cout<<(loads[i]?"true":"false");}std::cout<<"]}";
    }
    std::cout<<"]}\n";
    if(const char* feed=std::getenv("SCAMP_FEED_PID")){int status;waitpid(std::strtol(feed,nullptr,10),&status,0);}
